     * @param aircraft  (optional)
     * @param cruiseTasKt  (optional)
     * @param fuelBurnGph  (optional)
     * @param usableFuelGal  (optional)
     * @param climbTasKt  (optional)
     * @param climbFuelBurnGph  (optional)
     * @param descentIasKt  (optional)
     * @param descentFuelBurnGph  (optional)
     * @param cruisePowerPct  (optional)
     * @param serviceCeilingFt  (optional)
     * @param climbRateFpm  (optional)
     * @param taxiFuelGal  (optional)
     * @param glideRatio  (optional)
     * @param depart  (optional)
     * @param classBClearance  (optional, default to false)
     * @param rules  (optional, default to "vfr")
     * @param alternate  (optional, default to "")
     * @param altitudes  (optional, default to "")
     * @param altitudeStarts  (optional, default to "")
     * @param procedures  (optional, default to "")
     * @param runways  (optional, default to "")
